export interface CharacterEntry {
  unicode: string;
  char: string;
  description: string;
  html: string;
  example: string;
}

export interface CharacterCategoryGroup {
  name: string;
  items: CharacterEntry[];
}

export interface SpecialCharacterItem extends CharacterEntry {
  category: string;
}

function codePointToChar(codePointHex: string): string {
  try {
    const hex = codePointHex.replace(/^U\+/i, '').trim();
    const code = parseInt(hex, 16);
    if (isNaN(code)) return '';
    return String.fromCodePoint(code);
  } catch {
    return '';
  }
}

