/**
 * Flat lookup array with category injected for fast search.
 * Runs once at module initialization → O(1) category lookup, instant search.
 */
export const SPECIAL_CHARACTERS: SpecialCharacterItem[] = SPECIAL_CHARACTER_GROUPS.flatMap((group) =>
  group.items.map((item) => ({ ...item, category: group.name }))
);

/**
 * Unique category list with entry counts derived directly from the groups.
 */
export function getUniqueCategories(): { name: string; count: number }[] {
  return SPECIAL_CHARACTER_GROUPS.map((g) => ({
    name: g.name,
    count: g.items.length,
  }));
}
